def zaehle_vierbeiner(tiere):
    anzahl = 0
    for tier in tiere:
        if tier["beine"] > 4:
            anzahl += 1
    return anzahl

tiere = [{"beine": 4}, {"beine": 4}, {"beine": 2}]
print(zaehle_vierbeiner(tiere))

